=JOB DESCRIPTION:
Position: AI Automation Engineer (Junior).
Required: build n8n automation workflows; RAG chatbots; Gemini API (LLM integration); OpenAI API integration; Groq API integration; prompt engineering; Python; JavaScript; REST APIs and webhooks; JSON; Bachelor's degree in a relevant field; Arabic and English.
Nice to have: vector databases, Docker, SQL.

CANDIDATE PROFILE:
{{ JSON.stringify($json.output) }}

MOTIVATION: {{ $('Prepare Application').item.json.motivation || 'not provided' }}

CV TEXT:
{{ $('Prepare Application').item.json.cvText }}

parameters.jsCode:
const app = $('Prepare Application').item.json;
const profile = $('Extract Candidate Profile').item.json.output || {};
const ev = $json.output || {};
const problems = [];

const score = Number(ev.score);
if (!Number.isFinite(score) || score < 0 || score > 100) problems.push('score must be a number between 0 and 100');

const recommendation = String(ev.recommendation || '').toLowerCase().trim();
if (!['interview', 'maybe', 'reject'].includes(recommendation)) problems.push('recommendation must be interview, maybe or reject');

const arr = (v) => Array.isArray(v) ? v : [];
const matched = arr(ev.matched_requirements);
const missing = arr(ev.missing_requirements);
const questions = arr(ev.interview_questions);
if (!matched.length && !missing.length) problems.push('no requirements analysis returned');
if (questions.length < 1) problems.push('no interview questions returned');
if (!ev.strengths) problems.push('strengths is empty');
if (!ev.concerns) problems.push('concerns is empty');

const topSkills = Array.isArray(profile.topSkills) ? profile.topSkills.join(', ') : (profile.topSkills || '');

return {
  json: {
    appliedAt: app.appliedAt,
    name: app.name,
    email: app.email,
    position: app.position,
    motivation: app.motivation || '',
    readMethod: app.readMethod,
    cvFileId: app.cvFileId,
    score,
    recommendation,
    matched_requirements: matched,
    missing_requirements: missing,
    strengths: ev.strengths || '',
    concerns: ev.concerns || '',
    interview_questions: questions,
    yearsExperience: profile.yearsExperience ?? null,
    topSkills,
    valid: problems.length === 0,
    problems: problems.join('; ')
  }
};
